import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"الفصل 106 | صقل المراتب · مرتبة الإحساس بالأصل | مقارنة بين الجانب الافتراسي والجانب التكافلي","description":"","frontmatter":{"title":"الفصل 106 | صقل المراتب · مرتبة الإحساس بالأصل | مقارنة بين الجانب الافتراسي والجانب التكافلي","no":106,"module":1,"tags":["境界","感元境","掠夺派","共生派","路线对比"],"related":["04-掠夺式修炼体系批判","01-衡元宙核心世界观","14-修炼境界统一划分"]},"headers":[],"relativePath":"ar/0106_模块1-感元境-掠夺派vs共生派对比.md","filePath":"ar/0106_模块1-感元境-掠夺派vs共生派对比.md"}'),l={name:"ar/0106_模块1-感元境-掠夺派vs共生派对比.md"};function i(o,t,h,n,s,_){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="الفصل-106-مرتبة-الإحساس-بالأصل-مقارنة-منهجية-بين-الجانب-الافتراسي-والجانب-التكافلي" tabindex="-1">الفصل 106 | مرتبة الإحساس بالأصل: مقارنة منهجية بين الجانب الافتراسي والجانب التكافلي <a class="header-anchor" href="#الفصل-106-مرتبة-الإحساس-بالأصل-مقارنة-منهجية-بين-الجانب-الافتراسي-والجانب-التكافلي" aria-label="Permalink to &quot;الفصل 106 | مرتبة الإحساس بالأصل: مقارنة منهجية بين الجانب الافتراسي والجانب التكافلي&quot;">​</a></h1><blockquote><p>الوحدة: الوحدة الأولى · صقل المراتب المتعمق | الوثائق المرجعية: 04، 01، 14</p></blockquote><h2 id="مقدمة-منطقتا-استزراع،-كونان-مختلفان" tabindex="-1">مقدمة: منطقتا استزراع، كونان مختلفان <a class="header-anchor" href="#مقدمة-منطقتا-استزراع،-كونان-مختلفان" aria-label="Permalink to &quot;مقدمة: منطقتا استزراع، كونان مختلفان&quot;">​</a></h2><p>مرتبة الإحساس بالأصل ليست نقطة بدء الاستزراع فحسب، بل هي أيضًا أول مفترق في الرؤية الكونية: من أول امتصاص للطاقة، يكون المستزرِع واقفًا بالفعل على الشّعبة — إما «آخذ من العالم»، وإما «أنمو مع العالم». تبدو الجملتان متقاربتين، لكنهما تقودان إلى كونين مختلفين تمامًا: أحدهما باحة صيد حيث القوي يأكل الضعيف؛ والآخر مجتمع حياة حيث جميع الكائنات تصعد معًا.</p><p>يقدم هذا المقال المقارنة على المستوى المنهجي بين نظام الزراعة الافتراسية وحضارة التكافل المرساة.</p><p>البديهيات العليا الست هي خط الفصل نفسه: بديهية منع الافتراس تفصل بين «الأخذ» و«النمو»؛ وبديهية جمهورية عشرة آلاف عرق تفصل بين «عرقي وحدي» و«جميع الأعراق»؛ وبديهية الصعود البعدي الجماعي تفصل بين «أصعد وحدي» و«نصعد معًا»؛ وبديهية الانضباط السببي الذاتي تفصل بين «الدَّين في موضع آخر» و«أحمل ثمرة نفسي»؛ وبديهية أولوية القانون تفصل بين «قواعد لمصلحتي» و«قانون مستقر متسق». قانون المساواة اللانهائية الشاملة لجميع الكائنات يقرر أن كل كائن يحمل في ذاته القوة اللانهائية الأساسية: المستسلمون يحافظون على حد أدنى مضمون من اللانهاية ولا يُقصَون بفعل الأزمنة، بينما يمكن للدؤوبين والشباب الأعلى تكديس مستويات أعلى من اللانهاية. الأصل اللانهائي يحمله الجميع؛ منطق الافتراس «لا يحيا إلا الأقوياء» باطل من وجهه.</p><h2 id="أولًا-الجدول-الرئيسي-للمقارنة-المنهجية" tabindex="-1">أولًا. الجدول الرئيسي للمقارنة المنهجية <a class="header-anchor" href="#أولًا-الجدول-الرئيسي-للمقارنة-المنهجية" aria-label="Permalink to &quot;أولًا. الجدول الرئيسي للمقارنة المنهجية&quot;">​</a></h2><table tabindex="0"><thead><tr><th>البُعد</th><th>الجانب الافتراسي</th><th>الجانب التكافلي (المرساة)</th></tr></thead><tbody><tr><td>مصدر الطاقة</td><td>يلتهم أصل الغير</td><td>يأخذ من دورة العالم، ويُغذيها</td></tr><tr><td>الموقف من الضعفاء</td><td>انتقاء طبيعي، الضعيف ليمت</td><td>حاجز أمان للجميع، لا أحد يُترك خلفًا</td></tr><tr><td>منطق السقف</td><td>قمة واحدة فوق مقبرة</td><td>الكل يصعد معًا</td></tr><tr><td>الأفق الزمني</td><td>يستنزف الآن، ويُلقي لاحقًا</td><td>دوران ثنائي، مستدام</td></tr><tr><td>الموقف من الخطر</td><td>الخطر فلتر</td><td>الخطر مشكلة تُدار</td></tr><tr><td>الأساس الأخلاقي</td><td>القوة تصنع الحق</td><td>الانضباط السببي الذاتي</td></tr><tr><td>الوجهة القصوى</td><td>سيّد قطاع نجمي واحد</td><td>مرتبة المرساة المتوازنة فائقة التعددية</td></tr></tbody></table><h2 id="ثانيًا-مغالطات-الجانب-الافتراسي-الثلاث" tabindex="-1">ثانيًا. مغالطات الجانب الافتراسي الثلاث <a class="header-anchor" href="#ثانيًا-مغالطات-الجانب-الافتراسي-الثلاث" aria-label="Permalink to &quot;ثانيًا. مغالطات الجانب الافتراسي الثلاث&quot;">​</a></h2><ol><li>مغالطة المجموع صفري: يعتقد أن القوة ثابتة، فلكي يأخذها يجب أن يسلبها من غيره — أعمى عن أن طاقة دورة العالم متجددة ومتسعة.</li><li>مغالطة الانتقاء الطبيعي: يعتقد أن الضعفاء يستحقون أن يُنتَقوا — أعمى عن أن الحد الأدنى اللانهائي للمستسلمين يتيح للبطيء اللحاق دون أن يُسحق.</li><li>مغالطة «الافتراسي المستنير»: يعتقد أن الافتراسي الرحيم هو أفضل الافتراسيين — أعمى عن أن بنية الافتراس نفسها هي الداء، لا مزاج الافتراسي.</li></ol><h2 id="ثالثًا-«الافتراسي-المستنير»-والارتداد-التاريخي" tabindex="-1">ثالثًا. «الافتراسي المستنير» والارتداد التاريخي <a class="header-anchor" href="#ثالثًا-«الافتراسي-المستنير»-والارتداد-التاريخي" aria-label="Permalink to &quot;ثالثًا. «الافتراسي المستنير» والارتداد التاريخي&quot;">​</a></h2><p>المسمى الافتراسي المستنير — أي القوي الذي لا يقتل عبثًا، والذي «يتشارك القليل» مع الضعفاء، والذي يسمي نفسه محسنًا — هو أخطر أوهام الجانب الافتراسي الذاتية. الصياد اللطيف لا يزال صيادًا؛ ولطفه ليس سوى صقل لإدارة فريسته. يظهر التاريخ مرارًا أن عصر «الاستنارة» في نظام افتراسي هو دائمًا عشية الارتداد: ما إن تنفد باحات الصيد، حتى يكون المحسنون من الأقوياء أول من ينقلب على أهليهم.</p><h2 id="رابعًا-الوغد-العادل-تحذير-لـ«المختارين»" tabindex="-1">رابعًا. الوغد العادل: تحذير لـ«المختارين» <a class="header-anchor" href="#رابعًا-الوغد-العادل-تحذير-لـ«المختارين»" aria-label="Permalink to &quot;رابعًا. الوغد العادل: تحذير لـ«المختارين»&quot;">​</a></h2><p>الجانب التكافلي لا يدّعي أن جانبه كامل. الصيغة الأكثر مكرًا هي «الوغد العادل»: الذي يرتدي عباءة العدل ليواصل النهب، ويقول «أفعل هذا من أجل التكافل» وهو يستنزف غيره في ارتقائه.</p><p>لنأخذ لين هاو، بطل هذا الكون، حجر اختبار: طريقه ليس أن يصبح الأقوى في باحة صيد، بل أن يثبت أن القوي يمكنه الصعود مع ترك طريق عودة للضعفاء. كلما اغتُرَّ بقوله «أنا مميز، فالقواعد لا تنطبق عليّ»، كانت تلك هي اللحظة بالضبط التي يطرق فيها العدو الباطني للاختصار الباب — هذا هو الخط الداخلي الذي يجب أن يصونه كل مستزرِع في الجانب التكافلي.</p><h2 id="خامسًا-خمس-نقاط-ارتكاز-جوهرية" tabindex="-1">خامسًا. خمس نقاط ارتكاز جوهرية <a class="header-anchor" href="#خامسًا-خمس-نقاط-ارتكاز-جوهرية" aria-label="Permalink to &quot;خامسًا. خمس نقاط ارتكاز جوهرية&quot;">​</a></h2><ul><li>منع هدر مستوى الطاقة: «القوي يأكل الضعيف» لدى الجانب الافتراسي يهدر من الإمكان التطوري أكثر من أي حرب؛ والدوران الثنائي لدى الجانب التكافلي هو الكفاءة العالية الحقيقية.</li><li>منع الافتراس: كل صف في الجدول الرئيسي خط أحمر لا يعبره الجانب التكافلي.</li><li>مقارنة سقف تانغ لو: سقف الجانب الافتراسي سيّد فوق مقبرة؛ وسقف الجانب التكافلي يرفع الكون كله.</li><li>التغطية الكاملة لعشرة آلاف عرق: الجدول الرئيسي يغطي كل بُعد، من مصدر الطاقة إلى الوجهة القصوى، بلا زاوية عمياء.</li><li>الانفتاح الكامل فائق التعددية: المقارنة نفسها دليل مفتوح — الجانب الافتراسي لا يجرؤ على نشرها، لأن كل بُعد يفضح صغره.</li></ul><h2 id="خاتمة" tabindex="-1">خاتمة <a class="header-anchor" href="#خاتمة" aria-label="Permalink to &quot;خاتمة&quot;">​</a></h2><p>الجدول لا يحتاج إلى بلاغة؛ العمودان يتكلمان. في مرتبة الإحساس بالأصل، أول امتصاص يختاره المستزرِع يقرر في أي عمود سيقف بقية حياته — لذا وُضعت هذه المقارنة في أول المكتبة كلها: ليرى كل قارئ، قبل أن يختار الطريق، أي كون يوشك أن يدخله.</p><h2 id="روابط" tabindex="-1">روابط <a class="header-anchor" href="#روابط" aria-label="Permalink to &quot;روابط&quot;">​</a></h2><ul><li>الوثائق ذات الصلة: <a href="./04-掠夺式修炼体系批判.html">04-نقد نظام الزراعة الافتراسية</a> · <a href="./01-衡元宙核心世界观.html">01-الرؤية الكونية الجوهرية لهنغ يوانتشو</a> · <a href="./14-修炼境界统一划分.html">14-التقسيم الموحد لمراتب الاستزراع</a></li><li>الموقع الرسمي: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',21)])])}const p=a(l,[["render",i]]);export{u as __pageData,p as default};
